/**
 * Template Name: RudnikAgro â€” Kariera
 * Template Post Type: page
 */
get_header();
the_post();

$banner = get_field('rudnikagro_page_banner');
$vacancies = get_field('rudnikagro_vacancies');
$application_form = (int) get_field('rudnikagro_application_form');
$cta = get_field('rudnikagro_careers_cta');
$banner_image = !empty($banner['image']) ? (int) $banner['image'] : 0;
$cta_background = !empty($cta['background']) ? (int) $cta['background'] : 0;
$banner_url = $banner_image ? wp_get_attachment_image_url($banner_image, 'full') : '';
$cta_url = $cta_background ? wp_get_attachment_image_url($cta_background, 'full') : '';
?>

<?php if (!empty($banner['title'])) : ?>
  <section class="c-careers-banner" data-factory-section="careers-heading"<?php if ($banner_url) : ?> style="--careers-banner-image: url('<?php echo esc_url($banner_url); ?>');"<?php endif; ?>>
    <div class="l-container c-careers-banner__inner">
      <h1><?php echo esc_html($banner['title']); ?></h1>
    </div>
  </section>
<?php endif; ?>
<?php if (!empty($banner['breadcrumb'])) : ?><p class="c-careers-breadcrumb l-container"><?php echo esc_html($banner['breadcrumb']); ?></p><?php endif; ?>

<?php if ($vacancies) : ?>
  <section class="c-careers-vacancies" data-factory-section="careers-vacancies" aria-label="<?php echo esc_attr(get_the_title()); ?>">
    <div class="c-careers-vacancies__list">
      <?php foreach ($vacancies as $index => $vacancy) :
        $title = $vacancy['title'] ?? '';
        $description = $vacancy['description'] ?? '';
        $form_id = !empty($vacancy['application_form']) ? (int) $vacancy['application_form'] : $application_form;
        if ($title === '') { continue; }
      ?>
        <details class="c-career-vacancy"<?php echo $index === 0 ? ' open' : ''; ?>>
          <summary><span><?php echo esc_html($title); ?></span><span class="c-career-vacancy__icon" aria-hidden="true"></span></summary>
          <?php if ($description !== '') : ?>
            <div class="c-career-vacancy__body">
              <div class="c-career-vacancy__description"><?php echo wp_kses_post($description); ?></div>
              <?php if ($form_id) : ?><div class="c-career-application" id="career-application" data-factory-section="careers-application"><?php echo do_shortcode('[contact-form-7 id="' . $form_id . '"]'); ?></div><?php endif; ?>
            </div>
          <?php endif; ?>
        </details>
      <?php endforeach; ?>
    </div>
  </section>
<?php endif; ?>

<?php if (!empty($cta['heading'])) : ?>
  <section class="c-careers-cta" data-factory-section="shared-shop-cta"<?php if ($cta_url) : ?> style="--careers-cta-background: url('<?php echo esc_url($cta_url); ?>');"<?php endif; ?>>
    <div class="c-careers-cta__inner">
      <h2><?php echo esc_html($cta['heading']); ?></h2>
      <?php if (!empty($cta['button_label']) && $application_form) : ?><a href="#career-application" class="c-careers-cta__button"><?php echo esc_html($cta['button_label']); ?></a><?php endif; ?>
    </div>
  </section>
<?php endif; ?>

<?php get_footer(); ?>
@use 'abstracts' as *;

.c-careers-banner {
  background-color: #006633;
  background-image: var(--careers-banner-image);
  background-position: center;
  background-size: cover;
  color: $white;
  border-radius: 20px;
  margin: 24px auto 0;
  min-height: 220px;
  overflow: hidden;
  width: min(calc(100% - 40px), 1440px);

  &__inner { align-items: center; display: flex; flex-direction: column; justify-content: center; min-height: 220px; width: 100%; }
  h1 { font-size: 48px; font-weight: 700; line-height: 1; margin: 0; }
}

.c-careers-breadcrumb { font-size: 14px; margin-top: 8px; }
.c-careers-vacancies { margin: 19px auto 0; max-width: 1196px; }
.c-careers-vacancies__list { display: grid; gap: 20px; }

.c-career-vacancy {
  background: #f6f6f6;
  border: 1px solid #c8c8c8;
  border-radius: 30px;
  overflow: hidden;

  summary { align-items: center; background: #006633; color: $white; cursor: pointer; display: flex; font-size: 24px; font-weight: 700; justify-content: space-between; list-style: none; min-height: 114px; padding: 30px 50px; }
  summary::-webkit-details-marker { display: none; }
  &__icon { border: solid currentColor; border-width: 0 2px 2px 0; height: 12px; transform: rotate(45deg); transition: transform .2s ease; width: 12px; }
  &[open] .c-career-vacancy__icon { transform: rotate(225deg); }
  &__body { padding: 40px 100px 36px; }
  &__description { color: #11111b; font-size: 18px; line-height: 1.1705; margin-inline: -40px; }
  &__description p { margin: 0 0 24px; }
  &__description ul { list-style: disc outside; margin: -8px 0 24px; padding-left: 20px; }
  &__description li { margin: 0 0 3px; }
}

.c-career-application {
  margin-top: 30px;
  .wpcf7 { color: #11111b; }
  .wpcf7 form { display: grid; gap: 30px; grid-template: 'contact contact' 152px 'upload consents' 90px 'empty submit' 44px / 223px 1fr; margin: 0; }
